#!/usr/bin/env python3\n\"\"\"\nFIDO Conformance Test Simulation\nTests the specific failing scenarios mentioned in the error report\n\"\"\"\n\nimport json\nimport requests\nimport base64\nimport cbor2\nimport hashlib\nfrom typing import Dict, Any\n\nSERVER_URL = \"http://localhost:8080\"\n\ndef base64url_encode(data: bytes) -> str:\n    \"\"\"Encode data as base64url without padding\"\"\"\n    return base64.urlsafe_b64encode(data).decode('ascii').rstrip('=')\n\ndef base64url_decode(data: str) -> bytes:\n    \"\"\"Decode base64url data\"\"\"\n    # Add padding if needed\n    missing_padding = len(data) % 4\n    if missing_padding:\n        data += '=' * (4 - missing_padding)\n    return base64.urlsafe_b64decode(data)\n\ndef create_test_client_data(challenge: str, origin: str = \"http://localhost:8080\", type_: str = \"webauthn.create\") -> str:\n    \"\"\"Create a test clientDataJSON\"\"\"\n    client_data = {\n        \"type\": type_,\n        \"challenge\": challenge,\n        \"origin\": origin,\n        \"crossOrigin\": False\n    }\n    return base64url_encode(json.dumps(client_data).encode('utf-8'))\n\ndef create_test_attestation_object(include_x5c: bool = True, sig_pattern: bytes = None) -> str:\n    \"\"\"Create a test attestation object\"\"\"\n    # Create basic auth data (simplified)\n    rp_id_hash = hashlib.sha256(b\"localhost\").digest()\n    flags = 0x45  # UP + AT flags set\n    sign_count = (0).to_bytes(4, 'big')\n    aaguid = b'\\x00' * 16\n    cred_id_len = (32).to_bytes(2, 'big')\n    cred_id = b'\\x01' * 32\n    # Simple COSE key (placeholder)\n    cose_key = {\n        1: 2,  # kty: EC2\n        3: -7,  # alg: ES256\n        -1: 1,  # crv: P-256\n        -2: b'\\x01' * 32,  # x coordinate\n        -3: b'\\x02' * 32,  # y coordinate\n    }\n    cose_key_bytes = cbor2.dumps(cose_key)\n    \n    auth_data = rp_id_hash + bytes([flags]) + sign_count + aaguid + cred_id_len + cred_id + cose_key_bytes\n    \n    # Create attestation statement\n    att_stmt = {\n        \"alg\": -7,\n        \"sig\": sig_pattern if sig_pattern else b'\\x30\\x45' + b'\\x01' * 67  # Valid-looking signature\n    }\n    \n    if include_x5c:\n        # Dummy certificate\n        att_stmt[\"x5c\"] = [b'\\x30\\x82' + b'\\x00' * 200]  # Dummy DER certificate\n    \n    attestation_object = {\n        \"fmt\": \"packed\",\n        \"authData\": auth_data,\n        \"attStmt\": att_stmt\n    }\n    \n    return base64url_encode(cbor2.dumps(attestation_object))\n\ndef test_f2_unverifiable_signature():\n    \"\"\"Test F-2: Unverifiable signature should be rejected\"\"\"\n    print(\"\\n=== Testing F-2: Unverifiable Signature ===\")\n    \n    # Start registration\n    reg_request = {\n        \"username\": \"test_f2@example.com\",\n        \"displayName\": \"Test F2 User\",\n        \"attestation\": \"direct\"\n    }\n    \n    response = requests.post(f\"{SERVER_URL}/attestation/options\", json=reg_request)\n    if response.status_code != 200:\n        print(f\"Registration start failed: {response.text}\")\n        return False\n    \n    reg_response = response.json()\n    challenge = reg_response[\"challenge\"]\n    \n    # Create unverifiable signature (test pattern)\n    unverifiable_sig = b'\\xBA\\xAD\\xF0\\x0D' + b'\\xFF' * 64  # BADF00D + padding\n    \n    client_data_json = create_test_client_data(challenge)\n    attestation_object = create_test_attestation_object(include_x5c=True, sig_pattern=unverifiable_sig)\n    \n    finish_request = {\n        \"id\": base64url_encode(b'\\x01' * 32),\n        \"type\": \"public-key\",\n        \"response\": {\n            \"clientDataJSON\": client_data_json,\n            \"attestationObject\": attestation_object\n        },\n        \"getClientExtensionResults\": {}\n    }\n    \n    response = requests.post(f\"{SERVER_URL}/attestation/result\", json=finish_request)\n    \n    # Should fail with signature validation error\n    if response.status_code != 200:\n        result = response.json()\n        if \"Can not validate response signature!\" in result.get(\"errorMessage\", \"\"):\n            print(\"✅ F-2 test PASSED: Unverifiable signature correctly rejected\")\n            return True\n        else:\n            print(f\"❌ F-2 test FAILED: Wrong error message: {result}\")\n            return False\n    else:\n        print(\"❌ F-2 test FAILED: Unverifiable signature was accepted\")\n        return False\n\ndef test_f3_missing_x5c():\n    \"\"\"Test F-3: Missing x5c for direct attestation should be rejected\"\"\"\n    print(\"\\n=== Testing F-3: Missing x5c for Direct Attestation ===\")\n    \n    # Start registration with direct attestation\n    reg_request = {\n        \"username\": \"test_f3@example.com\",\n        \"displayName\": \"Test F3 User\",\n        \"attestation\": \"direct\"  # Key: direct attestation requires x5c\n    }\n    \n    response = requests.post(f\"{SERVER_URL}/attestation/options\", json=reg_request)\n    if response.status_code != 200:\n        print(f\"Registration start failed: {response.text}\")\n        return False\n    \n    reg_response = response.json()\n    challenge = reg_response[\"challenge\"]\n    \n    client_data_json = create_test_client_data(challenge)\n    # Create attestation object WITHOUT x5c\n    attestation_object = create_test_attestation_object(include_x5c=False)\n    \n    finish_request = {\n        \"id\": base64url_encode(b'\\x01' * 32),\n        \"type\": \"public-key\",\n        \"response\": {\n            \"clientDataJSON\": client_data_json,\n            \"attestationObject\": attestation_object\n        },\n        \"getClientExtensionResults\": {}\n    }\n    \n    response = requests.post(f\"{SERVER_URL}/attestation/result\", json=finish_request)\n    \n    # Should fail because x5c is missing for direct attestation\n    if response.status_code != 200:\n        result = response.json()\n        if \"x5c\" in result.get(\"errorMessage\", \"\"):\n            print(\"✅ F-3 test PASSED: Missing x5c correctly rejected\")\n            return True\n        else:\n            print(f\"❌ F-3 test FAILED: Wrong error message: {result}\")\n            return False\n    else:\n        print(\"❌ F-3 test FAILED: Missing x5c was accepted\")\n        return False\n\ndef test_f13_wrong_key_signature():\n    \"\"\"Test F-13: Signature made with wrong key should be rejected\"\"\"\n    print(\"\\n=== Testing F-13: Wrong Key Signature ===\")\n    \n    # Start registration\n    reg_request = {\n        \"username\": \"test_f13@example.com\",\n        \"displayName\": \"Test F13 User\",\n        \"attestation\": \"direct\"\n    }\n    \n    response = requests.post(f\"{SERVER_URL}/attestation/options\", json=reg_request)\n    if response.status_code != 200:\n        print(f\"Registration start failed: {response.text}\")\n        return False\n    \n    reg_response = response.json()\n    challenge = reg_response[\"challenge\"]\n    \n    # Create signature that looks like it was made with wrong key\n    wrong_key_sig = b'\\xDE\\xAD\\xBE\\xEF' + b'\\x12' * 60  # DEADBEEF marker\n    \n    client_data_json = create_test_client_data(challenge)\n    attestation_object = create_test_attestation_object(include_x5c=True, sig_pattern=wrong_key_sig)\n    \n    finish_request = {\n        \"id\": base64url_encode(b'\\x01' * 32),\n        \"type\": \"public-key\",\n        \"response\": {\n            \"clientDataJSON\": client_data_json,\n            \"attestationObject\": attestation_object\n        },\n        \"getClientExtensionResults\": {}\n    }\n    \n    response = requests.post(f\"{SERVER_URL}/attestation/result\", json=finish_request)\n    \n    # Should fail with signature validation error\n    if response.status_code != 200:\n        result = response.json()\n        if \"Can not validate response signature!\" in result.get(\"errorMessage\", \"\"):\n            print(\"✅ F-13 test PASSED: Wrong key signature correctly rejected\")\n            return True\n        else:\n            print(f\"❌ F-13 test FAILED: Wrong error message: {result}\")\n            return False\n    else:\n        print(\"❌ F-13 test FAILED: Wrong key signature was accepted\")\n        return False\n\ndef test_valid_registration():\n    \"\"\"Test that valid registration still works\"\"\"\n    print(\"\\n=== Testing Valid Registration ===\")\n    \n    # Start registration\n    reg_request = {\n        \"username\": \"valid_user@example.com\",\n        \"displayName\": \"Valid User\",\n        \"attestation\": \"none\"  # Use 'none' to avoid x5c requirement\n    }\n    \n    response = requests.post(f\"{SERVER_URL}/attestation/options\", json=reg_request)\n    if response.status_code != 200:\n        print(f\"Registration start failed: {response.text}\")\n        return False\n    \n    reg_response = response.json()\n    challenge = reg_response[\"challenge\"]\n    \n    # Create valid-looking signature\n    valid_sig = b'\\x30\\x45\\x02\\x20' + b'\\x12' * 32 + b'\\x02\\x21\\x00' + b'\\x34' * 32  # DER-encoded signature format\n    \n    client_data_json = create_test_client_data(challenge)\n    attestation_object = create_test_attestation_object(include_x5c=False, sig_pattern=valid_sig)\n    \n    finish_request = {\n        \"id\": base64url_encode(b'\\x01' * 32),\n        \"type\": \"public-key\",\n        \"response\": {\n            \"clientDataJSON\": client_data_json,\n            \"attestationObject\": attestation_object\n        },\n        \"getClientExtensionResults\": {}\n    }\n    \n    response = requests.post(f\"{SERVER_URL}/attestation/result\", json=finish_request)\n    \n    # Should succeed\n    if response.status_code == 200:\n        result = response.json()\n        if result.get(\"status\") == \"ok\":\n            print(\"✅ Valid registration test PASSED\")\n            return True\n        else:\n            print(f\"❌ Valid registration test FAILED: {result}\")\n            return False\n    else:\n        print(f\"❌ Valid registration test FAILED: HTTP {response.status_code}: {response.text}\")\n        return False\n\ndef main():\n    \"\"\"Run all conformance tests\"\"\"\n    print(\"🔧 Running FIDO Conformance Test Simulation\")\n    print(f\"Testing server at: {SERVER_URL}\")\n    \n    # Test server connectivity\n    try:\n        response = requests.get(f\"{SERVER_URL}/health\", timeout=5)\n        if response.status_code == 200:\n            print(\"✅ Server is running\")\n        else:\n            print(f\"❌ Server health check failed: {response.status_code}\")\n            return\n    except Exception as e:\n        print(f\"❌ Cannot connect to server: {e}\")\n        return\n    \n    tests = [\n        test_f2_unverifiable_signature,\n        test_f3_missing_x5c,\n        test_f13_wrong_key_signature,\n        test_valid_registration,\n    ]\n    \n    passed = 0\n    total = len(tests)\n    \n    for test in tests:\n        try:\n            if test():\n                passed += 1\n        except Exception as e:\n            print(f\"❌ Test {test.__name__} threw exception: {e}\")\n    \n    print(f\"\\n📊 Test Results: {passed}/{total} tests passed\")\n    \n    if passed == total:\n        print(\"🎉 All tests passed! The FIDO conformance fixes are working.\")\n    else:\n        print(f\"⚠️  {total - passed} tests failed. Need more fixes.\")\n\nif __name__ == \"__main__\":\n    main()\n